actions.script:
const stopped = ec.resource.script('component://tools/template/LoadRuns.js').call('stop#LoadRun',
    {runId: String(context.runId || ''), now: String(context.now) == 'true'})
ec.web.sendJsonResponse({errors: stopped.error})

const error = ec.resource.script('component://tools/template/LoadRuns.js').updateUsers(context.runId, context.scenario,
    context.users, context.rate)
ec.web.sendJsonResponse({errors: error || null})

const runId = String(context.runId || '')
const read = ec.resource.script('component://tools/template/LoadRuns.js').call('get#LoadRunResult', {runId})
if (read.error) ec.message.addError(read.error)
else ec.web.sendTextResponse(JSON.stringify(read.out.result || {}, null, 2), 'application/json',
    'load-' + runId.replace(/[^A-Za-z0-9_-]/g, '_') + '.json')
